<?php include 'views/layouts/header.php'; $icons=['cliente'=>'fa-users','pago'=>'fa-dollar-sign','equipo'=>'fa-wifi','visita'=>'fa-helmet-safety']; ?>
<div class="container-fluid py-4 px-lg-4"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 fw-bold mb-1">Actividad del sistema</h1><p class="text-muted mb-0">Historial comprobable de operaciones almacenadas en SkyNetwork.</p></div><a href="<?php echo url('dashboard'); ?>" class="btn btn-outline-primary">Volver al dashboard</a></div><div class="card"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead class="table-light"><tr><th>Fecha</th><th>Tipo</th><th>Descripción</th><th>Relacionado</th><th>Monto</th><th>Estado</th></tr></thead><tbody><?php if(!$activities): ?><tr><td colspan="6" class="text-center text-muted py-5">Aún no hay actividad registrada.</td></tr><?php else: foreach($activities as $a): ?><tr><td><?php echo htmlspecialchars(date('d/m/Y H:i',strtotime(str_replace('T',' ',$a['fecha'])))); ?></td><td><i class="fas <?php echo $icons[$a['tipo']]??'fa-circle'; ?> text-primary me-2"></i><?php echo ucfirst(htmlspecialchars($a['tipo'])); ?></td><td><?php echo htmlspecialchars($a['descripcion']); ?></td><td><?php echo htmlspecialchars($a['relacionado']); ?></td><td><?php echo $a['monto']===null?'—':'$'.number_format((float)$a['monto'],2); ?></td><td><?php echo htmlspecialchars(ucfirst(str_replace('_',' ',$a['estado']))); ?></td></tr><?php endforeach; endif; ?></tbody></table></div></div></div>
